-- UI text, one row per (language, key) (2026-10-13).
--
--   docker exec -i lemp-mysql mysql -u localguideapp -p'…' guideapp < api/sql/018_translations.sql
--
-- IF NOT EXISTS-guarded; the seed below upserts, so re-running it resets
-- every seeded value (English and the 13 translations) to this file's text —
-- after a CMS has edited rows, re-run it only if that's what you want.
--
-- Keys are namespaced `{page}.{widget}.{key}` — `page` is the route's page
-- (`discover`, `guide_profile`, …) or `common` for shared components and
-- helpers, whose `widget` is then the component (`common.booking_panel.pay`).
-- Values may contain `{placeholder}`s; plural forms are separate keys with a
-- CLDR suffix (`_zero`, `_one`, `_two`, `_few`, `_many`, `_other`). Served by the
-- `translations` API action (`Translations.php`). The client bundles the same
-- English as a fallback (`client/src/i18n/en.json`), from which the seed below
-- is generated — keep the two in step.
CREATE TABLE IF NOT EXISTS `translations` (
  `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `language`   VARCHAR(10)  NOT NULL,
  `key`        VARCHAR(191) NOT NULL,
  `value`      TEXT         NOT NULL,
  `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `translations_language_key` (`language`, `key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

